  "private": true,
  "scripts": {
    "prepare:runtime": "node scripts/prepare-runtime.js",
    "start": "electron .",
    "package:app": "node scripts/package.js",
    "installer": "node scripts/build-installer.js",
    "typecheck": "tsc --noEmit",
    "build:types": "tsc"
  },
  "devDependencies": {
    "@types/node": "^22.10.10",
    "electron": "^33.2.0",
