'use strict';

/**
 * Open Notebook Desktop — Electron main process.
 *
 * Bundles and launches the full Open Notebook stack (SurrealDB, FastAPI
 * backend, background worker, Next.js frontend) and presents it in a native
 * desktop window.
 */

const { app, BrowserWindow, shell, dialog } = require('electron');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { startServices } = require('./scripts/start-services');

const FRONTEND_URL = 'http://127.0.0.1:8502';

function resolveRuntimePath() {
  if (app.isPackaged) {
    return path.join(process.resourcesPath, 'runtime');
  }
  return path.join(__dirname, 'resources', 'runtime');
}

function ensureEncryptionKey(dataDir) {
  const keyFile = path.join(dataDir, 'encryption-key.txt');
  if (fs.existsSync(keyFile)) {
    return fs.readFileSync(keyFile, 'utf8').trim();
  }
  const key = crypto.randomBytes(32).toString('hex');
  fs.mkdirSync(dataDir, { recursive: true });
  fs.writeFileSync(keyFile, key, 'utf8');
  return key;
}

let services = null;
let mainWindow = null;
let shuttingDown = false;

async function stopServices() {
  if (shuttingDown) return;
  shuttingDown = true;
  if (services) {
    try {
      await services.stop();
    } catch (err) {
      console.error('Error stopping services:', err);
    }
  }
}

function showErrorAndExit(title, message) {
  // Use a synchronous message box so the app waits for the user to click OK
  // before exiting. dialog.showErrorBox is also synchronous on Windows.
  dialog.showErrorBox(title, message);
  app.exit(1);
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1440,
    height: 900,
    minWidth: 1024,
    minHeight: 700,
    title: 'Office of Equity Open Notebook',
    backgroundColor: '#0b0b0f',
    autoHideMenuBar: true,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  mainWindow.loadURL(FRONTEND_URL);

  // Open external links in the system browser, not inside the app.
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    if (url.startsWith('http://') || url.startsWith('https://')) {
      shell.openExternal(url);
    }
    return { action: 'deny' };
  });

  mainWindow.webContents.on('will-navigate', (event, url) => {
    if (!url.startsWith(FRONTEND_URL)) {
      event.preventDefault();
      if (url.startsWith('http://') || url.startsWith('https://')) {
        shell.openExternal(url);
      }
    }
  });

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

app.whenReady().then(async () => {
  const runtimePath = resolveRuntimePath();
  const dataDir = app.getPath('userData');
  const encryptionKey = ensureEncryptionKey(dataDir);

  const required = [
    path.join(runtimePath, 'surreal', 'surreal.exe'),
    path.join(runtimePath, 'backend', 'open_notebook'),
    path.join(runtimePath, 'frontend', 'server.js'),
  ];
  const missing = required.filter((p) => !fs.existsSync(p));
  if (missing.length > 0) {
    showErrorAndExit(
      'Office of Equity Open Notebook — runtime not found',
      'The bundled runtime is incomplete. Please re-run `npm run prepare:runtime` and rebuild the app.\n\nMissing:\n' +
        missing.join('\n')
    );
    return;
  }

  try {
    services = await startServices({
      runtimePath,
      dataDir,
      encryptionKey,
      waitReady: true,
    });
  } catch (err) {
    showErrorAndExit('Office of Equity Open Notebook — failed to start', String(err && err.message));
    return;
  }

  createWindow();
});

app.on('window-all-closed', async () => {
  await stopServices();
  app.quit();
});

app.on('before-quit', (event) => {
  if (!shuttingDown) {
    event.preventDefault();
    stopServices().finally(() => {
      app.quit();
    });
  }
});

'use strict';

/**
 * start-services.js
 *
 * Spawns the four Open Notebook services (SurrealDB, FastAPI backend,
 * background worker, Next.js frontend) as child processes and exposes a
 * single `stop()` to tear them all down.
 *
 * This module is used both by the Electron main process (dev + packaged) and
 * by the standalone `scripts/run-services.js` CLI for headless verification.
 */

const { spawn, execFileSync } = require('child_process');
const net = require('net');
const path = require('path');
const fs = require('fs');

const PORTS = {
  surreal: 8000,
  api: 5055,
  frontend: 8502,
};

/**
 * Resolve a bundled executable, falling back to a command on PATH.
 * Returns the absolute path or null if not found.
 */
function findOnPath(command) {
  try {
    const result = execFileSync('where', [command], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    const first = result.split('\n').find((line) => line.trim());
    return first ? first.trim() : null;
  } catch (_) {
    return null;
  }
}

function resolvePython(runtimePath) {
  const bundled = path.join(runtimePath, 'python', 'python.exe');
  if (fs.existsSync(bundled)) return { path: bundled, source: 'bundled' };

  const system = findOnPath('python.exe') || findOnPath('python');
  if (!system) return null;

  // The backend requires Python >=3.11 and <3.13.
  try {
    const out = execFileSync(system, ['--version'], { encoding: 'utf8' }).trim();
    const m = out.match(/Python (\d+)\.(\d+)/);
    if (!m) return null;
    const major = parseInt(m[1], 10);
    const minor = parseInt(m[2], 10);
    if (major !== 3 || minor < 11 || minor >= 13) {
      return { path: system, source: 'system', invalidVersion: `${major}.${minor}` };
    }
    return { path: system, source: 'system' };
  } catch (_) {
    return null;
  }
}

function resolveNode(runtimePath) {
  const bundled = path.join(runtimePath, 'node', 'node.exe');
  if (fs.existsSync(bundled)) return { path: bundled, source: 'bundled' };

  const system = findOnPath('node.exe') || findOnPath('node');
  if (!system) return null;

  try {
    const out = execFileSync(system, ['--version'], { encoding: 'utf8' }).trim();
    const m = out.match(/v(\d+)/);
    if (!m) return null;
    const major = parseInt(m[1], 10);
    if (major < 18) {
      return { path: system, source: 'system', invalidVersion: major };
    }
    return { path: system, source: 'system' };
  } catch (_) {
    return null;
  }
}

function isPortOpen(port, host = '127.0.0.1') {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    const onDone = (ok) => {
      socket.destroy();
      resolve(ok);
    };
    socket.setTimeout(1000);
    socket.once('connect', () => onDone(true));
    socket.once('timeout', () => onDone(false));
    socket.once('error', () => onDone(false));
    socket.connect(port, host);
  });
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function waitForPort(port, timeoutMs = 60000, label = String(port)) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await isPortOpen(port)) return true;
    await sleep(500);
  }
  throw new Error(`Timed out waiting for ${label} on port ${port}`);
}

/**
 * Start all services.
 * @param {object} cfg
 * @param {string} cfg.runtimePath  Path to the assembled runtime folder.
 * @param {string} cfg.dataDir      Directory for user data (db, uploads, logs).
 * @param {string} cfg.encryptionKey OPEN_NOTEBOOK_ENCRYPTION_KEY value.
 * @param {boolean} cfg.waitReady   Wait for the frontend to be reachable.
 */
async function startServices(cfg) {
  const { runtimePath, dataDir, encryptionKey } = cfg;
  const backendPath = path.join(runtimePath, 'backend');
  const surrealExe = path.join(runtimePath, 'surreal', 'surreal.exe');
  const frontendDir = path.join(runtimePath, 'frontend');
  const tiktokenCache = path.join(runtimePath, 'tiktoken-cache');

  // Resolve Python and Node: bundled runtime first, then system PATH.
  const python = resolvePython(runtimePath);
  if (!python) {
    throw new Error(
      'Python 3.11/3.12 was not found. Either install the bundled Python runtime, ' +
        'or ensure python.exe for Python 3.11 or 3.12 is on your PATH.'
    );
  }
  if (python.invalidVersion) {
    throw new Error(
      `Python ${python.invalidVersion} was found at ${python.path}, but the backend requires Python 3.11 or 3.12. ` +
        'Install the bundled Python runtime or a supported system Python.'
    );
  }

  const node = resolveNode(runtimePath);
  if (!node) {
    throw new Error(
      'Node.js was not found. Either install the bundled Node.js runtime, ' +
        'or ensure node.exe (v18+) is on your PATH.'
    );
  }
  if (node.invalidVersion) {
    throw new Error(
      `Node.js ${node.invalidVersion} was found at ${node.path}, but the frontend server requires Node.js v18+. ` +
        'Install the bundled Node.js runtime or upgrade your system Node.js.'
    );
  }

  const pythonExe = python.path;
  const nodeExe = node.path;

  for (const p of [backendPath, dataDir]) {
    fs.mkdirSync(p, { recursive: true });
  }
  fs.mkdirSync(path.join(dataDir, 'surrealdb'), { recursive: true });
  const logsDir = path.join(dataDir, 'logs');
  fs.mkdirSync(logsDir, { recursive: true });

  // Check for port conflicts before starting anything.
  for (const [name, port] of Object.entries(PORTS)) {
    if (await isPortOpen(port)) {
      throw new Error(
        `Port ${port} is already in use (${name}). Another Open Notebook instance or another service is running. Close it and try again.`
      );
    }
  }

  // The backend resolves the database migrations and DATA_FOLDER relative to
  // its working directory. We run it from the backend dir so the migrations
  // resolve, and point DATA_FOLDER at the user-data directory so all user data
  // (uploads, sqlite, podcasts) lives outside the read-only app resources.
  const dataFolder = path.join(dataDir, 'data');
  fs.mkdirSync(dataFolder, { recursive: true });

  const backendEnv = {
    ...process.env,
    PYTHONPATH: backendPath,
    PYTHONUNBUFFERED: '1',
    PYTHONUTF8: '1',
    DATA_FOLDER: dataFolder,
    SURREAL_URL: 'ws://127.0.0.1:8000/rpc',
    SURREAL_USER: 'root',
    SURREAL_PASSWORD: 'root',
    SURREAL_NAMESPACE: 'open_notebook',
    SURREAL_DATABASE: 'open_notebook',
    OPEN_NOTEBOOK_ENCRYPTION_KEY: encryptionKey,
    // Docling is pre-installed into the bundled runtime by prepare-runtime.js,
    // so it is always enabled in the desktop app.
    OPEN_NOTEBOOK_ENABLE_DOCLING: 'true',
    TIKTOKEN_CACHE_DIR: tiktokenCache,
    API_HOST: '127.0.0.1',
    API_PORT: String(PORTS.api),
  };

  const children = [];
  const logStreams = new Map();

  function getLogStream(name) {
    if (!logStreams.has(name)) {
      const file = path.join(logsDir, `${name}.log`);
      const stream = fs.createWriteStream(file, { flags: 'a' });
      logStreams.set(name, stream);
    }
    return logStreams.get(name);
  }

  function logLine(name, stream, data) {
    const line = String(data).trimEnd();
    if (!line) return;
    const tag = `[${name}:${stream}]`;
    const timestamp = new Date().toISOString();
    const formatted = `${timestamp} ${tag} ${line}\n`;
    const outStream = getLogStream(name);
    outStream.write(formatted);
    // Also mirror to the parent console for dev/debug visibility.
    if (stream === 'err') {
      console.error(formatted.trimEnd());
    } else {
      console.log(formatted.trimEnd());
    }
  }

  function spawnService(name, cmd, args, opts) {
    const child = spawn(cmd, args, {
      cwd: opts.cwd || dataDir,
      env: opts.env || backendEnv,
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    child.stdout.on('data', (d) => logLine(name, 'out', d));
    child.stderr.on('data', (d) => logLine(name, 'err', d));
    child.on('error', (err) => console.error(`[${name}] spawn error: ${err.message}`));
    child.on('exit', (code, signal) => {
      const msg = `[${name}] exited (code=${code}, signal=${signal})`;
      logLine(name, 'out', msg);
      // If a critical service exits unexpectedly, surface it.
      if (code !== 0 && code !== null && !child.killed) {
        console.error(`CRITICAL: ${name} exited unexpectedly. Check ${path.join(logsDir, `${name}.log`)}`);
      }
    });
    children.push(child);
    return child;
  }

  // 1. SurrealDB
  const surrealDbFile = path.join(dataDir, 'surrealdb', 'mydatabase.db');
  spawnService(
    'surrealdb',
    surrealExe,
    ['start', '--log', 'info', '--user', 'root', '--pass', 'root', '--bind', `127.0.0.1:${PORTS.surreal}`, `rocksdb:${surrealDbFile}`],
    { cwd: dataDir, env: backendEnv }
  );
  await waitForPort(PORTS.surreal, 60000, 'SurrealDB');

  // 2. FastAPI backend
  spawnService(
    'api',
    pythonExe,
    ['-m', 'uvicorn', 'api.main:app', '--host', '127.0.0.1', '--port', String(PORTS.api)],
    { cwd: backendPath, env: backendEnv }
  );
  await waitForPort(PORTS.api, 120000, 'API');

  // 3. Background worker
  spawnService(
    'worker',
    pythonExe,
    ['-m', 'surreal_commands.cli.worker', '--import-modules', 'commands', '--max-tasks', '5'],
    { cwd: backendPath, env: backendEnv }
  );

  // 4. Next.js frontend (standalone server)
  const frontendEnv = {
    ...process.env,
    NODE_ENV: 'production',
    PORT: String(PORTS.frontend),
    HOSTNAME: '127.0.0.1',
    INTERNAL_API_URL: `http://127.0.0.1:${PORTS.api}`,
  };
  spawnService('frontend', nodeExe, ['server.js'], { cwd: frontendDir, env: frontendEnv });

  if (cfg.waitReady !== false) {
    await waitForPort(PORTS.frontend, 120000, 'Frontend');
  }

  return {
    children,
    ports: { ...PORTS },
    async stop() {
      // Kill in reverse order (frontend, worker, api, surreal)
      for (const child of [...children].reverse()) {
        try {
          if (!child.killed) child.kill();
        } catch (_) {
          /* ignore */
        }
      }
      // Give them a moment, then force-kill anything left.
      await sleep(1500);
      for (const child of children) {
        try {
          if (child.exitCode === null && !child.killed) {
            child.kill('SIGKILL');
          }
        } catch (_) {
          /* ignore */
        }
      }
      // Close log file streams.
      for (const stream of logStreams.values()) {
        try {
          stream.end();
        } catch (_) {
          /* ignore */
        }
      }
    },
  };
}

module.exports = { startServices, PORTS, isPortOpen, waitForPort };

'use strict';

/**
 * run-services.js — headless CLI to start/stop the bundled Open Notebook
 * services without launching the Electron window. Useful for testing and
 * debugging the runtime.
 *
 * Usage:
 *   node scripts/run-services.js --runtime <path> --data <dir> [--key <key>]
 */

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { startServices } = require('./start-services');

function arg(name, def) {
  const i = process.argv.indexOf(name);
  if (i !== -1 && process.argv[i + 1]) return process.argv[i + 1];
  return def;
}

async function main() {
  const runtime = arg('--runtime', path.join(__dirname, '..', 'resources', 'runtime'));
  const data = arg('--data', path.join(__dirname, '..', 'resources', '.testdata'));
  const key =
    arg('--key', null) ||
    (() => {
      const kf = path.join(data, 'encryption-key.txt');
      if (fs.existsSync(kf)) return fs.readFileSync(kf, 'utf8').trim();
      const k = crypto.randomBytes(32).toString('hex');
      fs.mkdirSync(data, { recursive: true });
      fs.writeFileSync(kf, k);
      return k;
    })();

  console.log('Starting services...');
  const services = await startServices({ runtimePath: runtime, dataDir: data, encryptionKey: key, waitReady: true });
  console.log('All services are up.');
  console.log('  Frontend: http://127.0.0.1:8502');
  console.log('  API:      http://127.0.0.1:5055/docs');
  console.log('  Database: ws://127.0.0.1:8000');
  console.log('Press Ctrl+C to stop.');

  const stop = async () => {
    console.log('Stopping services...');
    await services.stop();
    process.exit(0);
  };
  process.on('SIGINT', stop);
  process.on('SIGTERM', stop);
}

main().catch((err) => {
  console.error('Failed to start services:', err && err.message);
  process.exit(1);
});

/**
 * Office of Equity Open Notebook — Service Table Contract & Utilities
 */

import {
  ServiceTable,
  ServiceDefinition,
  ServicePorts,
  BackendEnvironment,
} from '../types';

export const DEFAULT_PORTS: ServicePorts = Object.freeze({
  surreal: 8000,
  api: 5055,
  frontend: 8502,
});

export const SERVICE_TABLE: ServiceTable = Object.freeze({
  version: '1.0.0',
  defaultPorts: DEFAULT_PORTS,
  services: [
    {
      name: 'surrealdb',
      command: 'surreal',
      args: ['start', '--log', 'info', '--user', 'root', '--pass', 'root'],
      readinessPolicy: {
        type: 'port' as const,
        port: DEFAULT_PORTS.surreal,
        timeoutMs: 60000,
        label: 'SurrealDB',
      },
    },
    {
      name: 'api',
      command: 'python',
      args: ['-m', 'uvicorn', 'api.main:app'],
      readinessPolicy: {
        type: 'port' as const,
        port: DEFAULT_PORTS.api,
        timeoutMs: 120000,
        label: 'API',
      },
    },
    {
      name: 'worker',
      command: 'python',
      args: ['-m', 'surreal_commands.cli.worker', '--import-modules', 'commands', '--max-tasks', '5'],
      readinessPolicy: {
        type: 'process' as const,
      },
    },
    {
      name: 'frontend',
      command: 'node',
      args: ['server.js'],
      readinessPolicy: {
        type: 'port' as const,
        port: DEFAULT_PORTS.frontend,
        timeoutMs: 120000,
        label: 'Frontend',
      },
    },
  ],
});

export function validateServiceDefinition(def: unknown): ServiceDefinition {
  if (typeof def !== 'object' || def === null) {
    throw new TypeError('ServiceDefinition must be an object');
  }
  const d = def as Record<string, unknown>;
  if (typeof d['name'] !== 'string' || d['name'].trim() === '') {
    throw new TypeError('ServiceDefinition.name must be a non-empty string');
  }
  if (typeof d['command'] !== 'string' || d['command'].trim() === '') {
    throw new TypeError('ServiceDefinition.command must be a non-empty string');
  }
  if (!Array.isArray(d['args']) || !d['args'].every((a) => typeof a === 'string')) {
    throw new TypeError('ServiceDefinition.args must be an array of strings');
  }
  return {
    name: d['name'],
    command: d['command'],
    args: d['args'] as string[],
    cwd: typeof d['cwd'] === 'string' ? d['cwd'] : undefined,
    env: typeof d['env'] === 'object' && d['env'] !== null ? (d['env'] as Record<string, string>) : undefined,
    readinessPolicy: typeof d['readinessPolicy'] === 'object' && d['readinessPolicy'] !== null
      ? (d['readinessPolicy'] as ServiceDefinition['readinessPolicy'])
      : undefined,
  };
}

export function validateServiceTable(table: unknown): ServiceTable {
  if (typeof table !== 'object' || table === null) {
    throw new TypeError('ServiceTable must be an object');
  }
  const t = table as Record<string, unknown>;
  if (typeof t['version'] !== 'string') {
    throw new TypeError('ServiceTable.version must be a string');
  }
  if (typeof t['defaultPorts'] !== 'object' || t['defaultPorts'] === null) {
    throw new TypeError('ServiceTable.defaultPorts must be an object');
  }
  if (!Array.isArray(t['services'])) {
    throw new TypeError('ServiceTable.services must be an array');
  }

  const validatedServices = t['services'].map((s) => validateServiceDefinition(s));

  return {
    version: t['version'],
    defaultPorts: t['defaultPorts'] as ServicePorts,
    services: validatedServices,
  };
}

export function createBackendEnvironment(params: {
  backendPath: string;
  dataFolder: string;
  encryptionKey: string;
  tiktokenCache: string;
  apiPort?: number | undefined;
  existingEnv?: Record<string, string | undefined> | undefined;
}): BackendEnvironment {
  const {
    backendPath,
    dataFolder,
    encryptionKey,
    tiktokenCache,
    apiPort = DEFAULT_PORTS.api,
    existingEnv = process.env,
  } = params;

  return {
    ...existingEnv,
    PYTHONPATH: backendPath,
    PYTHONUNBUFFERED: '1',
    PYTHONUTF8: '1',
    DATA_FOLDER: dataFolder,
    SURREAL_URL: 'ws://127.0.0.1:8000/rpc',
    SURREAL_USER: 'root',
    SURREAL_PASSWORD: 'root',
    SURREAL_NAMESPACE: 'open_notebook',
    SURREAL_DATABASE: 'open_notebook',
    OPEN_NOTEBOOK_ENCRYPTION_KEY: encryptionKey,
    OPEN_NOTEBOOK_ENABLE_DOCLING: 'true',
    TIKTOKEN_CACHE_DIR: tiktokenCache,
    API_HOST: '127.0.0.1',
    API_PORT: String(apiPort),
  };
}

/**
 * Office of Equity Open Notebook — Boundary Contracts & Interfaces
 *
 * Explicit TypeScript definitions for wrapper infrastructure, services,
 * runtimes, problem reports, process handles, and lifecycle boundaries.
 */

// ============================================================================
// Service & Process Boundary Contracts
// ============================================================================

export type ServiceName = 'surrealdb' | 'api' | 'worker' | 'frontend' | (string & {});

export type PortName = 'surreal' | 'api' | 'frontend';

export type ServicePorts = Record<PortName, number>;

export interface ServiceReadinessPolicy {
  type: 'port' | 'process' | 'none';
  port?: number | undefined;
  timeoutMs?: number | undefined;
  label?: string | undefined;
}

export interface ServiceDefinition {
  name: ServiceName;
  command: string;
  args: readonly string[];
  cwd?: string | undefined;
  env?: Record<string, string | undefined> | undefined;
  readinessPolicy?: ServiceReadinessPolicy | undefined;
}

export interface ServiceHandle {
  name: ServiceName;
  pid?: number | undefined;
  killed: boolean;
  exitCode: number | null;
  signal?: string | null | undefined;
}

export interface ServiceExitEvent {
  serviceName: ServiceName;
  exitCode: number | null;
  signal: string | null;
  unexpected: boolean;
  timestamp: string;
}

export interface ServiceTable {
  version: string;
  defaultPorts: ServicePorts;
  services: readonly ServiceDefinition[];
}

export interface StartServicesConfig {
  runtimePath: string;
  dataDir: string;
  encryptionKey: string;
  waitReady?: boolean | undefined;
  customPorts?: Partial<ServicePorts> | undefined;
}

export interface StartServicesResult {
  children: readonly ServiceHandle[];
  ports: ServicePorts;
  stop: () => Promise<ShutdownResult>;
}

export interface ShutdownResult {
  success: boolean;
  stoppedServices: readonly ServiceName[];
  errors?: readonly string[] | undefined;
  durationMs?: number | undefined;
}

// ============================================================================
// Process Identity & Resource Management Contracts
// ============================================================================

export interface ProcessIdentity {
  pid: number;
  name: string;
  commandLine?: string | undefined;
  parentPid?: number | undefined;
