const { spawn, execFileSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const {
  DEFAULT_SERVICE_PORTS,
  isPortOpen,
  waitForPort,
  formatLogLine,
  calculateShutdownSequence,
  validateStartServicesConfig,
} = require('../dist/src/contracts/process-manager');

const {
  resolvePython: resolvePythonContract,
  resolveNode: resolveNodeContract,
} = require('../dist/src/contracts/runtime-resolution');

const {
  createBackendEnvironment,
} = require('../dist/src/contracts/service-table');

const PORTS = DEFAULT_SERVICE_PORTS;

/**
 * Resolve a bundled executable, falling back to a command on PATH.
 * Returns the absolute path or null if not found.
 */
function findOnPath(command) {
  try {
    const result = execFileSync('where', [command], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    const first = result.split('\n').find((line) => line.trim());
    return first ? first.trim() : null;
  } catch (_) {
    return null;
  }
}

function getVersion(cmdPath, args) {
  try {
    return execFileSync(cmdPath, args, { encoding: 'utf8' }).trim();
  } catch (_) {
    return null;
  }
}

function resolvePython(runtimePath) {
  return resolvePythonContract(runtimePath, {
    fileExists: fs.existsSync,
    findOnPath,
    getVersion,
    pathJoin: path.join,
  });
}

function resolveNode(runtimePath) {
  return resolveNodeContract(runtimePath, {
    fileExists: fs.existsSync,
    findOnPath,
    getVersion,
    pathJoin: path.join,
  });
}

/**
 * Start all services.
 * @param {object} cfg
 * @param {string} cfg.runtimePath  Path to the assembled runtime folder.
 * @param {string} cfg.dataDir      Directory for user data (db, uploads, logs).
